const svgCaptcha = require('svg-captcha');

// 1. 生成验证码：服务端渲染图片，答案存 session
app.get('/api/captcha', (req, res) => {
  const c = svgCaptcha.create({ noise: 3, color: true });
  req.session.captcha = c.text.toLowerCase(); // 答案只存服务端
  req.session.captchaAt = Date.now();
  res.type('svg').send(c.data);
});

// 2. 校验：比对后立即销毁，防止复用
app.post('/api/login', (req, res) => {
  const ok = req.body.captcha?.toLowerCase() === req.session.captcha
    && Date.now() - req.session.captchaAt < 120000;
  delete req.session.captcha;
  if (!ok) return res.status(400).json({ msg: '验证码错误' });
  // ... 继续登录逻辑
});

