app.post('/api/login', async (req, res) => {
  const params = new URLSearchParams({
    secret: process.env.RECAPTCHA_SECRET, response: req.body.token });
  const r = await fetch('https://www.recaptcha.net/recaptcha/api/siteverify',
    { method: 'POST', body: params }).then(r => r.json());
  if (!r.success || r.action !== 'login')
    return res.status(403).json({ msg: '验证异常' });
  if (r.score < 0.5) // 阈值按业务自定
    return res.status(403).json({ msg: '风险较高，请完成短信验证', stepUp: true });
  // ... 正常登录
});

