  return res.status(403).json({ msg: '存在风险，交易已拦截' });
});

const redis = require('redis').createClient();
const code = String(Math.floor(100000 + Math.random() * 900000));

// 发送：限流 + 存码（5 分钟过期）
app.post('/api/sms/send', async (req, res) => {
  const { phone } = req.body;
  if (await redis.get(`sms:limit:${phone}`)) // 1条/分钟
    return res.status(429).json({ msg: '操作频繁，请稍后再试' });
  await redis.set(`sms:code:${phone}`, code, { EX: 300 });
  await redis.set(`sms:limit:${phone}`, 1, { EX: 60 });
  await smsProvider.send(phone, `您的验证码是${code}，5分钟内有效`);
  res.json({ ok: true });
});

// 校验：比对一致立即核销
app.post('/api/sms/verify', async (req, res) => {
  const real = await redis.get(`sms:code:${req.body.phone}`);
  if (real && real === req.body.code) {
    await redis.del(`sms:code:${req.body.phone}`); // 一次性核销
    return res.json({ ok: true });
  }
  res.status(400).json({ msg: '验证码错误或已过期' });
});

