const crypto = require('crypto');

// 1. 跳转授权页：state 防 CSRF
app.get('/auth/github', (req, res) => {
  const state = crypto.randomBytes(16).toString('hex');
  req.session.oauthState = state;
  const url = `https://github.com/login/oauth/authorize?client_id=${CLIENT_ID}&redirect_uri=${REDIRECT_URI}&state=${state}`;
  res.redirect(url);
});

// 2. 回调：校验 state → code 换 token → 拉用户信息
app.get('/auth/github/callback', async (req, res) => {
  if (req.query.state !== req.session.oauthState)
    return res.status(403).send('state 校验失败');
  const t = await fetch('https://github.com/login/oauth/access_token', {
    method: 'POST', headers: { Accept: 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET, code: req.query.code })
  }).then(r => r.json());
  const user = await fetch('https://api.github.com/user',
    { headers: { Authorization: `Bearer ${t.access_token}` } }).then(r => r.json());
  req.session.user = { id: `github:${user.id}`, name: user.login };
  res.redirect('/');
});

