const crypto = require('crypto');

// 下发：每个会话一个随机 token
app.use((req, res, next) => {
  req.session.csrfToken ||= crypto.randomBytes(32).toString('hex');
  next();
});
app.get('/api/csrf-token', (req, res) => res.json({ token: req.session.csrfToken }));

// 校验：变更加请求必须携带匹配的 token
app.use('/api', (req, res, next) => {
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next();
  const sent = req.headers['x-csrf-token'];
  // 攻击者跨站读不到受害者页面的 token（同源策略），伪造的请求必然缺 token
  if (!sent || sent !== req.session.csrfToken)
    return res.status(403).json({ msg: 'CSRF 校验失败' });
  next();
});

