  // 1. 用 token 向服务商换取真实手机号（token 一次性）
  const r = await fetch('https://dypnsapi.aliyuncs.com/', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ Action: 'GetMobile', AccessToken: token,
      /* + 阿里云 AK 签名参数，略 */ })
  }).then(r => r.json());
  if (r.Code !== 'OK') {
    return res.status(400).json({ msg: '取号失败，请用短信验证码登录', fallback: 'sms' });
  }
  // 2. 按手机号登录/注册
  const user = await findOrCreateUserByPhone(r.GetMobileResultDTO.Mobile);
  finishLogin(req, res, user);
});
